"""Spin words greater than five char long in a string.

    preserving white spaces
    """
def spin_words(sentence: Any) -> object {
    temp = [];
    spl = sentence.split();
    for char in spl {
        if (len(char) >= 5) {
            spin = char[::-1];
            temp.append(spin);
        } else {
            temp.append(char);
        }
    }
    output = ' '.join(temp);
    return output;
}

""" Return a list of all slots for a type, or object.

    Args:
        T: the type, or object to determine the slots for.

    Returns:
        The list of slot names, including those in base classes.
    """
def _all_slots(T: Any) -> object {
    if not isinstance(T, `type) {
        T = `type(T);
    }
    slots = [];
    def inner(T: Any, slots: Any) -> object {
        if hasattr(T, '__slots__') {
            slots += [s for s in T.__slots__];
        }
        for c in T.__bases__ {
            inner(c, slots);
        }
    }
    inner(T, slots);
    return slots;
}

